WITH synthetic_nice_asthma_diagnosis_population AS (SELECT column1::NUMBER AS person_id, column2::DATE AS reporting_date, column3::NUMBER AS age, column4::VARCHAR AS practice_code, column5::VARCHAR AS practice_name FROM VALUES (-9701,'2026-08-31',12,'SYNTHETIC','Synthetic practice'), (-9701,'2026-09-30',12,'SYNTHETIC','Synthetic practice'), (-9702,'2026-08-31',11,'SYNTHETIC','Synthetic practice'), (-9702,'2026-09-30',11,'SYNTHETIC','Synthetic practice'), (-9703,'2026-08-31',50,'SYNTHETIC','Synthetic practice'), (-9703,'2026-09-30',50,'SYNTHETIC','Synthetic practice'), (-9704,'2026-08-31',50,'SYNTHETIC','Synthetic practice'), (-9704,'2026-09-30',50,'SYNTHETIC','Synthetic practice'), (-9705,'2026-08-31',50,'SYNTHETIC','Synthetic practice'), (-9705,'2026-09-30',50,'SYNTHETIC','Synthetic practice'), (-9706,'2026-08-31',50,'SYNTHETIC','Synthetic practice'), (-9706,'2026-09-30',50,'SYNTHETIC','Synthetic practice')),
synthetic_events_0 AS (SELECT column1::NUMBER AS person_id, column2::DATE AS reporting_date, column3::BOOLEAN AS is_higher_risk, column4::DATE AS risk_period_start, column5::DATE AS risk_period_end, column6::NUMBER AS saba_inhaler_count, column7::NUMBER AS oral_steroid_course_count, column8::DATE AS latest_asthma_admission_date, column9::BOOLEAN AS has_high_saba_use, column10::BOOLEAN AS has_repeated_oral_steroids, column11::BOOLEAN AS has_asthma_admission FROM VALUES (-9701,'2026-08-31',TRUE,'2024-09-30','2025-09-30',6,0,NULL,TRUE,FALSE,FALSE), (-9701,'2026-09-30',TRUE,'2024-09-30','2025-09-30',6,0,NULL,TRUE,FALSE,FALSE), (-9702,'2026-08-31',TRUE,'2024-09-30','2025-09-30',6,0,NULL,TRUE,FALSE,FALSE), (-9702,'2026-09-30',TRUE,'2024-09-30','2025-09-30',6,0,NULL,TRUE,FALSE,FALSE), (-9703,'2026-08-31',TRUE,'2024-09-30','2025-09-30',6,0,NULL,TRUE,FALSE,FALSE), (-9703,'2026-09-30',TRUE,'2024-09-30','2025-09-30',6,0,NULL,TRUE,FALSE,FALSE), (-9704,'2026-08-31',TRUE,'2024-09-30','2025-09-30',6,0,NULL,TRUE,FALSE,FALSE), (-9704,'2026-09-30',TRUE,'2024-09-30','2025-09-30',6,0,NULL,TRUE,FALSE,FALSE), (-9705,'2026-08-31',TRUE,'2024-09-30','2025-09-30',6,0,NULL,TRUE,FALSE,FALSE), (-9705,'2026-09-30',TRUE,'2024-09-30','2025-09-30',6,0,NULL,TRUE,FALSE,FALSE), (-9706,'2026-08-31',FALSE,'2024-09-30','2025-09-30',6,0,NULL,TRUE,FALSE,FALSE), (-9706,'2026-09-30',TRUE,'2024-09-30','2025-09-30',6,0,NULL,TRUE,FALSE,FALSE)),
synthetic_events_1 AS (SELECT column1::NUMBER AS person_id, column2::DATE AS order_date FROM VALUES (-9701,'2025-09-30'), (-9702,'2026-08-01'), (-9703,'2026-08-31'), (-9703,'2026-09-30'), (-9703,'2026-10-01'), (-9704,'2026-08-01'), (-9705,'2026-10-01'), (-9706,'2026-08-01')),
synthetic_events_2 AS (SELECT column1::NUMBER AS person_id, column2::DATE AS event_date FROM VALUES (-9701,'2020-01-01'), (-9702,'2020-01-01'), (-9703,'2026-08-31'), (-9703,'2026-10-01'), (-9704,'2026-10-01'), (-9705,'2020-01-01'), (-9706,'2020-01-01')),
actual AS (SELECT person_id, reporting_date, is_in_numerator FROM ({{ query }})),
expected AS (SELECT column1::NUMBER AS person_id, column2::DATE AS reporting_date, column3::BOOLEAN AS is_in_numerator FROM VALUES (-9701,'2026-08-31',TRUE), (-9701,'2026-09-30',FALSE), (-9703,'2026-08-31',TRUE), (-9703,'2026-09-30',TRUE), (-9704,'2026-08-31',FALSE), (-9704,'2026-09-30',FALSE), (-9705,'2026-08-31',FALSE), (-9705,'2026-09-30',FALSE), (-9706,'2026-09-30',TRUE)),
actual_counts AS (SELECT *, COUNT(*) AS occurrences FROM actual GROUP BY ALL),
expected_counts AS (SELECT *, COUNT(*) AS occurrences FROM expected GROUP BY ALL),
failures AS ((SELECT * FROM actual_counts EXCEPT SELECT * FROM expected_counts) UNION ALL (SELECT * FROM expected_counts EXCEPT SELECT * FROM actual_counts))
SELECT COUNT(*) AS failure_count FROM failures HAVING COUNT(*) > 0
